    "mga_susing_tao": [
      {
        "pangalan": "Frederick Law Olmsted",
        "deskripsyon": "Pangunahing landscape architect na nagdisenyo ng parke. Ang kanyang pilosopiya ay lumikha ng isang pastoral at payapang tanawin na magsisilbing útakasan mula sa magulong buhay-lungsod."
      },
      {
        "pangalan": "Calvert Vaux",
        "deskripsyon": "Arkitekto at katuwang ni Olmsted sa disenyo. Siya ang responsable sa maraming istruktura at tulay sa loob ng parke."
      },
      {
        "pangalan": "Robert Moses",
        "deskripsyon": "Isang maimpluwensyang urban planner ng NYC noong ika-20 siglo. Bagama't nagdagdag siya ng mga pasilidad tulad ng Prospect Park Zoo at Wollman Rink, ang kanyang mga proyektong nakasentro sa sasakyan ay nagbago sa ilang bahagi ng orihinal na disenyo ng parke."
      },
      {
        "pangalan": "Prospect Park Alliance",
        "deskripsyon": "Isang non-profit na organisasyon na itinatag noong 1987. Sila ay nakikipagtulungan sa Lungsod ng New York upang pangalagaan, ipanumbalik, at pagandahin ang parke sa pamamagitan ng pribadong pondo at suporta ng komunidad."
      }
    ],
    "timeline_ng_kasaysayan": [
      {
        "panahon": "1859-1865: Pagpaplano at Pagkaantala",
        "mga_pangyayari": "```Noong 1859, itinalaga ng Lehislatura ng Estado ng New York ang lupain para sa isang malaking parke sa Brooklyn. Gayunpaman, ang pagsiklab ng Digmaang Sibil (Civil War) ay nag-antala sa pag-unlad ng proyekto. Sa panahong ito, sina Olmsted at Vaux ay tinanggap upang suriin at baguhin ang orihinal na plano, na nagresulta sa isang mas mahusay na disenyo.```"
      },
      {
        "panahon": "1866-1873: Konstruksyon at 'Golden Age'",
        "mga_pangyayari": "```Nagsimula ang konstruksyon noong 1866. Libu-libong manggagawa ang nagbago sa tanawin, nagtanim ng daan-daang libong puno, at lumikha ng mga pangunahing tampok tulad ng Long Meadow, ang Ravine, at ang Lake. Ang parke ay opisyal na binuksan noong 1867 at mabilis na naging isang tanyag na destinasyon.```"
      },
      {
        "panahon": "1890s-1930s: Mga Pagdaragdag at Pagbabago",
        "mga_pangyayari": "```Sa panahong ito, idinagdag ang ilang mga engrandeng istruktura sa istilong Beaux-Arts, kabilang ang Boathouse, ang Willink Hill (ngayon ay Lefferts Historic House) entrance, at ang Peristyle. Ang Grand Army Plaza, kasama ang Soldiers' and Sailors' Arch, ay nakumpleto rin bilang engrandeng pasukan ng parke.```"
      },
      {
        "panahon": "1940s-1970s: Panahon ng Pagsasalat at Pagpapabaya",
        "mga_pangyayari": "```Dahil sa mga krisis sa ekonomiya at pagbawas sa badyet ng lungsod, ang parke ay unti-unting napabayaan. Ang mga imprastraktura ay nasira, ang mga tanawin ay hindi naalagaan, at ang parke ay naging hindi ligtas sa ilang lugar. Ito ang pinakamadilim na panahon sa kasaysayan ng parke.```"
      },
      {
        "panahon": "1980-Kasalukuyan: Muling Pagsilang at Pagpapanumbalik",
        "mga_pangyayari": "```Bilang tugon sa pagkasira ng parke, itinatag ang Prospect Park Alliance noong 1987. Ang partnership na ito sa pagitan ng komunidad at ng gobyerno ay naglunsad ng malawakang pagsisikap sa pagpapanumbalik. Milyun-milyong dolyar ang nalikom upang ayusin ang mga makasaysayang istruktura tulad ng Boathouse at Carousel, at upang muling buhayin ang mga natural na lugar tulad ng Ravine.```"
      }
    ],
    "mga_pangunahing_tampok_na_lugar": [
      {
        "lugar": "Long Meadow",
        "deskripsyon": "Isang malawak na damuhan na may habang halos isang milya, na sinasabing pinakamahabang tuluy-tuloy na urban meadow sa Estados Unidos. Ito ay sentro para sa palakasan at pagrerelaks."
      },
      {
        "lugar": "The Ravine",
        "deskripsyon": "Ang tanging kagubatan sa Brooklyn, na may mga sapa at talon. Ito ay sumailalim sa isang malaking restorasyon upang maibalik ang orihinal na disenyo ni Olmsted."
      },
      {
        "lugar": "Prospect Park Lake",
        "deskripsyon": "Isang 60-acre na lawa na sikat para sa pamamangka, pangingisda, at bird-watching."
      },
      {
        "lugar": "Boathouse at Audubon Center",
        "deskripsyon": "Isang makasaysayang gusali sa istilong Beaux-Arts na ngayon ay nagsisilbing unang urban Audubon Center sa bansa, na nakatuon sa edukasyon tungkol sa kalikasan."
      },
      {
        "lugar": "Lefferts Historic House",
        "deskripsyon": "Isang ika-18 siglong Dutch-American farmhouse na inilipat sa parke noong 1918. Ito ngayon ay isang museo na nagpapakita ng buhay sa Brooklyn noong unang panahon."
      },
      {
        "lugar": "Grand Army Plaza",
        "deskripsyon": "Ang engrandeng pasukan sa hilagang bahagi ng parke, na kilala sa Soldiers' and Sailors' Arch, isang monumento para sa mga sundalo ng Union Army."
      }
    ],
    "kahalagahan_ngayon": "```Sa kasalukuyan, ang Prospect Park ay nananatiling 'Likod-bahay ng Brooklyn' (Brooklyn's Backyard). Ito ay isang masiglang sentro para sa libangan, kultura, at komunidad, na nagho-host ng mga konsiyerto, palakasan, farmers' market, at nagsisilbing isang mahalagang berdeng espasyo para sa milyun-milyong residente at bisita bawat taon. Ang matagumpay na pagpapanumbalik nito sa pamamagitan ng Prospect Park Alliance ay isang modelo para sa mga urban park sa buong mundo.```"
  }
}
```

